// ─── Migration ─────────────────────────────────────────────────────────────

const ROOT_PATH = join(import.meta.dirname, '..')
const dataPath = join(ROOT_PATH, 'data/regulations.json')

const laws = JSON.parse(readFileSync(dataPath, 'utf8')) as { id: string; [k: string]: unknown }[]

let updated = 0
let missing = 0

for (const law of laws) {
  const positions = POSITIONS[law.id]
  if (positions) {
    law.issue_positions = positions
    updated++
  } else {
    console.warn(`⚠  No issue positions for: ${law.id}`)
    missing++
  }
}

writeFileSync(dataPath, JSON.stringify(laws, null, 2))

console.log(`✓ Updated ${updated} laws with issue_positions`)
if (missing > 0) console.warn(`⚠  ${missing} laws had no positions defined`)
